$base='http://localhost/hls-v2/public';$cookie=tempnam(sys_get_temp_dir(),'c');function req($u,$p=null){global $cookie;$ch=curl_init($u);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>1,CURLOPT_COOKIEFILE=>$cookie,CURLOPT_COOKIEJAR=>$cookie,CURLOPT_FOLLOWLOCATION=>0]);if($p!==null){curl_setopt($ch,CURLOPT_POST,1);curl_setopt($ch,CURLOPT_POSTFIELDS,$p);} $h=curl_exec($ch);$c=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);return [$c,$h];}
[, $h]=req($base.'/login');preg_match('/name="csrf" value="([^"]+)/',$h,$m);req($base.'/login',['csrf'=>$m[1],'email'=>'demo_finance@demo.invalid','password'=>'123456']);foreach([6000000,4000000] as $v){[, $h]=req($base.'/finance/invoices');preg_match('/name="csrf" value="([^"]+)/',$h,$m);req($base.'/finance/invoices',['csrf'=>$m[1],'branch_id'=>1,'customer_id'=>1,'invoice_date'=>'2026-10-25','due_date'=>'2026-11-25','description[]'=>'Invoice Reversal Uji','quantity[]'=>1,'unit_price[]'=>$v]);}$db=new PDO('mysql:host=127.0.0.1;dbname=hls_v2','root','');$ids=array_map('intval',$db->query("SELECT id FROM fin_invoices WHERE internal_ref LIKE 'INV-DRAFT-%' AND status='DRAFT' ORDER BY id DESC LIMIT 2")->fetchAll(PDO::FETCH_COLUMN));sort($ids);foreach($ids as $id){[, $h]=req($base.'/finance/invoice-detail?id='.$id);preg_match('/name="csrf" value="([^"]+)/',$h,$m);req($base.'/finance/invoice-issue',['csrf'=>$m[1],'id'=>$id]);}[, $h]=req($base.'/finance/payments');preg_match('/name="csrf" value="([^"]+)/',$h,$m);$ref='PAY-REV-UJI-'.date('His');[$pc,$out]=req($base.'/finance/payments',['csrf'=>$m[1],'account_id'=>1,'payment_date'=>'2026-10-25','payment_ref'=>$ref,'invoice_id[]'=>[$ids[0],$ids[1]],'allocation[]'=>[6000000,1000000]]);$pid=$db->query("SELECT id FROM fin_payments WHERE payment_ref='$ref'")->fetchColumn();[, $h]=req($base.'/finance/payments');preg_match('/name="csrf" value="([^"]+)/',$h,$m);[$rc,$ro]=req($base.'/finance/payments',['csrf'=>$m[1],'action'=>'reverse','payment_id'=>$pid,'reason'=>'Koreksi transaksi pengujian reversal']);echo json_encode(['ids'=>$ids,'ref'=>$ref,'pid'=>$pid,'payment_code'=>$pc,'reverse_code'=>$rc,'body'=>substr(strip_tags($ro),0,160)]),PHP_EOL;unlink($cookie);

